{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid acid closely related to the query scaffold, has an absolute oral bioavailability of approximately 60% (range 36–95%) after a single oral dose in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Etretinate, a highly lipophilic non-ionized retinoid ester, has an absolute oral bioavailability of 44 ± 14% (range 30–70%) compared with intravenous administration in volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, a retinoic acid isomer, has a systemic bioavailability of 40% at a therapeutic oral dose in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Oral all-trans retinoic acid bioavailability was estimated at 25–30% in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "13-cis-retinoic acid was described as having low absolute bioavailability with significant gut degradation, providing a contradictory low-bioavailability signal for the retinoid class.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a lipophilic retinoid anilide. Transferable evidence from closely related retinoids—acitretin (~60%), etretinate (~40–44%), isotretinoin (~40%), and ATRA (~25–52%)—consistently supports oral bioavailability at or above 20%. The few low/erratic ATRA reports are outweighed by quantitative retinoid data and do not establish F < 20% for the query.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide itself is present in the evidence set.",
    "Fenretinide-specific effects of poor aqueous solubility, formulation, and first-pass metabolism on F are not directly addressed by the available records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

